class Solution:
    def countWays(self, n: int, k: int) -> int:
        M = 10**9 + 7
        dp = [1] + [0] * k
        for i in range(1, n + 1):
            for j in range(min(i, k), 0, -1): dp[j] = (j * dp[j] + dp[j - 1]) % M
            dp[0] = 0
        return dp[k]

