#include <bits/stdc++.h>
using namespace std;
const long long M=1e9+7;
long long pw(long long b,long long e){long long r=1;b%=M;while(e){if(e&1)r=r*b%M;b=b*b%M;e>>=1;}return r;}
int main(){ int n,k; cin>>n>>k; // inclusion-exclusion: S(n,k) = 1/k! * sum (-1)^j C(k,j) (k-j)^n
  vector<long long> f(k+1,1); for(int i=1;i<=k;i++) f[i]=f[i-1]*i%M;
  long long s=0; for(int j=0;j<=k;j++){ long long c=f[k]*pw(f[j],M-2)%M*pw(f[k-j],M-2)%M; long long t=c*pw(k-j,n)%M; s=(j&1)?(s-t+M)%M:(s+t)%M; }
  cout<<s*pw(f[k],M-2)%M<<"\n"; }

